export const DEPTH_SCHEMA='devfleet.education.lesson-depth.v1';
export function lessonDepth(material){
  if(!material||!Number.isInteger(material.subject)||!SUBJECT_DEPTH[material.subject])
    throw Error('education_subject_depth_invalid');
  const pack=SUBJECT_DEPTH[material.subject];
  return {
    schema:DEPTH_SCHEMA,objective:pack.objective,glossary:pack.glossary.map(([term,meaning])=>({term,meaning})),
    extension:pack.extension,commonMistake:pack.commonMistake,reflection:pack.reflection,
    spotlight:spotlights[material.id]??null,
    references:pack.resources.map(key=>resources[key])
  };
}
export const ALLOWED_RESOURCE_URLS=Object.freeze([...new Set(Object.values(resources).map(x=>x.url))]);
